 if(ext[13]){const s=dec.decode(u8.slice(ext[13].off,ext[13].off+ext[13].count));s.split("\t").forEach(p=>{const i=p.indexOf("=");if(i<0)return;const sh=p.slice(0,i).trim(),lg=p.slice(i+1).replace(/\u0000/g,"").trim();const v=vars.find(x=>x.name.toUpperCase()===sh.toUpperCase());if(v)v.name=lg})}
