function qtukey(p,cc,df){let lo=0,hi=50;for(let i=0;i<80;i++){const m=(lo+hi)/2;ptukey(m,cc,df)<p?lo=m:hi=m}return(lo+hi)/2}


/* ===== Post hoc: Tukey HSD, S-N-K, Duncan, Games-Howell, Tamhane T2 + homogeneous subsets ===== */
function postHocExtra(c,gs,msw,dfw,F,v){let h="";const k=gs.length;if(k<3)return h;const m=gs.map(x=>ST.mean(x.g)),n=gs.map(x=>x.g.length),sd=gs.map(x=>x.g.length>1?ST.sd(x.g):0),lab=i=>labOf(F,gs[i].c);const alpha=+c.alpha||.05;
 const pairs=(fn,name,note)=>{const rows=[];for(let a=0;a<k;a++)for(let b=0;b<k;b++){if(a===b)continue;const r=fn(a,b);rows.push([lab(a)+" vs "+lab(b),fmtN(m[a]-m[b],4)+(r.p<=alpha?"*":""),fmtN(r.se,4),pf(r.p),fmtN(m[a]-m[b]-r.ci,4),fmtN(m[a]-m[b]+r.ci,4)])}h+=otb(`Multiple Comparisons — ${name} — ${v.name}`,["(I) vs (J)","Mean Difference (I-J)","Std. Error","Sig.","95% CI Lower","95% CI Upper"],rows)+(note?onote(note):"")};
 if(c.tukey){const qc=qtukey(1-alpha,k,dfw);pairs((a,b)=>{const se=Math.sqrt(msw*(1/n[a]+1/n[b])/2),q=Math.abs(m[a]-m[b])/se;return{se:se*Math.SQRT2,p:1-ptukey(q,k,dfw),ci:qc*se}},"Tukey HSD")}
 if(c.gh){pairs((a,b)=>{const va=sd[a]**2/n[a],vb=sd[b]**2/n[b],se=Math.sqrt(va+vb),df=(va+vb)**2/(va*va/(n[a]-1)+vb*vb/(n[b]-1)),q=Math.abs(m[a]-m[b])/se*Math.SQRT2;return{se,p:1-ptukey(q,k,df),ci:qtukey(1-alpha,k,df)*se/Math.SQRT2}},"Games-Howell","لا يفترض تجانس التباين — مناسب عندما يكون اختبار ليفين دالًا.")}
 if(c.t2){const mm=k*(k-1)/2;pairs((a,b)=>{const va=sd[a]**2/n[a],vb=sd[b]**2/n[b],se=Math.sqrt(va+vb),df=(va+vb)**2/(va*va/(n[a]-1)+vb*vb/(n[b]-1)),p=ST.tP2((m[a]-m[b])/se,df);return{se,p:Math.min(1,1-Math.pow(1-p,mm)),ci:ST.tcrit(df,1-Math.pow(1-alpha,1/mm))*se}},"Tamhane T2","لا يفترض تجانس التباين.")}
 const subsets=(name,critP)=>{const ord=[...Array(k).keys()].sort((a,b)=>m[a]-m[b]),nh=k/n.reduce((s,x)=>s+1/x,0),se=Math.sqrt(msw/nh);const ok=(i,j)=>{const r=j-i+1;if(r<2)return{ok:true,p:1};const q=(m[ord[j]]-m[ord[i]])/se;const p=critP(q,r);return{ok:p>alpha,p}};const subs=[];for(let i=0;i<k;i++){let j=k-1;while(j>i&&!ok(i,j).ok)j--;if(!subs.some(s=>s[0]<=i&&s[1]>=j))subs.push([i,j])}
  const rows=ord.map((g,idx)=>[lab(g),n[g],...subs.map(s=>idx>=s[0]&&idx<=s[1]?fmtN(m[g],4):"")]);rows.push(["Sig.","",...subs.map(s=>pf(ok(s[0],s[1]).p))]);h+=otb(`${v.name} — ${name} (Homogeneous Subsets)`,[F.name,"N",...subs.map((_,i)=>"Subset "+(i+1))],rows)+onote(`المتوسطات في نفس العمود لا تختلف دالًا عند ${alpha}. حجم العينة المستخدم = المتوسط التوافقي ${fmtN(nh,3)}.`)};
 if(c.tukey)subsets("Tukey HSD",(q)=>1-ptukey(q,k,dfw));
 if(c.snk)subsets("Student-Newman-Keuls",(q,r)=>1-ptukey(q,r,dfw));
 if(c.duncan)subsets("Duncan",(q,r)=>{const p=1-ptukey(q,r,dfw);return 1-Math.pow(1-p,1/(r-1))});
 return h}
/* ===== Bootstrap (percentile & BCa) ===== */
function mulberry(seed){return()=>{seed|=0;seed=seed+0x6D2B79F5|0;let t=Math.imul(seed^seed>>>15,1|seed);t=t+Math.imul(t^t>>>7,61|t)^t;return((t^t>>>14)>>>0)/4294967296}}
