function bootTable(title,rows,c){return otb(`Bootstrap for ${title}`,["","Statistic","Bias","Std. Error",`${c.bootci||95}% CI Lower`,"Upper"],rows.map(([l,r])=>[l,fmtN(r.est,4),fmtN(r.bias,4),fmtN(r.se,4),fmtN(r.lo,4),fmtN(r.hi,4)]))+onote(`a. نتائج Bootstrap مبنية على ${c.bootn||1000} عينة (${c.boottype==="bca"?"BCa":"Percentile"}). فترة الثقة التي لا تحتوي الصفر تعني أن الفرق دال.`)}

