/* ===== Dunnett's test: multivariate-t probability by numerical integration ===== */
function _simpson(f,a,b,n){if(n%2)n++;const h=(b-a)/n;let s=f(a)+f(b);for(let i=1;i<n;i++)s+=(i%2?4:2)*f(a+i*h);return s*h/3}
