 autoMeasure(){let c=0;DS.vars.forEach((v,j)=>{if(v.type!=="n")return;const a=nOK(DS.rows.map(r=>numOrNull(r[j])));const u=new Set(a).size;const m=u<=2||Object.keys(v.values).length>=u?"nominal":u<=7&&a.every(Number.isInteger)?"ordinal":"scale";if(m!==v.measure){v.measure=m;c++}});dsSave();toast(`تم ضبط مستوى القياس لـ ${c} متغير`);SA.tab="var"},
