 means(){if(!needVars(1)||DS.vars.length<2)return toast("تحتاج متغيرًا تابعًا ومتغير مجموعات");dlg("Means",`<label class="fl">Dependent List</label>${vpick("mnv",numVars(),true)}${vsel("mnf",DS.vars.map((v,j)=>({v,j})),"Independent List (Layer 1)")}`,()=>{const js=picked("mnv");if(!js.length){toast("اختر متغيرًا");return false}aMeans(js,+$("#mnf").value)})},
 sumt(){dlg("Summary Independent-Samples T Test",`<p class="muted" style="margin-top:0">أدخل الإحصاءات الملخصة بدون بيانات خام.</p><div class="g2"><div><b>Sample 1</b><label class="fl">N</label><input type="number" id="s1n" value="30"><label class="fl">Mean</label><input type="number" step="any" id="s1m" value="11.92"><label class="fl">Std. Deviation</label><input type="number" step="any" id="s1s" value="1.25"></div><div><b>Sample 2</b><label class="fl">N</label><input type="number" id="s2n" value="22"><label class="fl">Mean</label><input type="number" step="any" id="s2m" value="13.62"><label class="fl">Std. Deviation</label><input type="number" step="any" id="s2s" value="0.89"></div></div>`,()=>{const a={n:+$("#s1n").value,m:+$("#s1m").value,sd:+$("#s1s").value},b={n:+$("#s2n").value,m:+$("#s2m").value,sd:+$("#s2s").value};if(a.n<2||b.n<2||!(a.sd>0)||!(b.sd>0)){toast("قيم غير صالحة");return false}aSumT(a,b)})},
 glm(){if(!needVars(1)||DS.vars.length<2)return toast("تحتاج متغيرًا تابعًا وعاملًا");const ALL=DS.vars.map((v,j)=>({v,j}));dlg("Univariate (Two-Way ANOVA)",vsel("gld",numVars(),"Dependent Variable")+vsel("glf1",ALL,"Fixed Factor 1")+`<label class="fl" for="glf2">Fixed Factor 2 (اختياري)</label><select id="glf2"><option value="">— لا يوجد —</option>${ALL.map(x=>`<option value="${x.j}">${esc(x.v.name)}</option>`).join("")}</select>`,()=>{const f1=+$("#glf1").value,f2v=$("#glf2").value;const fs=[f1];if(f2v!==""&&+f2v!==f1)fs.push(+f2v);if(fs.includes(+$("#gld").value)){toast("العامل لا يكون هو المتغير التابع");return false}aGLM(+$("#gld").value,fs)})},
 rm(){if(!needVars(2))return;dlg("Repeated Measures (One Within-Subjects Factor)",`<label class="fl">Within-Subjects Variables (القياسات بالترتيب)</label>${vpick("rmv2",numVars(),true)}`,()=>{const js=picked("rmv2");if(js.length<2){toast("اختر قياسين على الأقل");return false}aRM(js)})},
 partial(){if(!needVars(3))return;dlg("Partial Correlations",`<label class="fl">Variables</label>${vpick("pcv",numVars(),true)}<label class="fl">Controlling for</label>${vpick("pcc",numVars(),true)}`,()=>{const js=picked("pcv"),cs=picked("pcc").filter(c=>!js.includes(c));if(js.length<2||!cs.length){toast("اختر متغيرين ومتغير ضبط مختلف");return false}aPartial(js,cs)})},
 reg(){if(!needVars(2))return;dlg("Linear Regression",vsel("rgd",numVars(),"Dependent — المتغير التابع")+`<label class="fl">Independent(s) — المنبئات</label>${vpick("rgi",numVars(),true)}<p class="muted" style="font-size:13.5px">Method: Enter. يعرض R²، ANOVA، المعاملات، Beta، VIF، Durbin-Watson.</p>`,()=>{const d=+$("#rgd").value,iv=picked("rgi").filter(x=>x!==d);if(!iv.length){toast("اختر منبئًا واحدًا على الأقل");return false}aReg(d,iv)})},
 logit(){if(!needVars(1))return;dlg("Logistic Regression",vsel("lgd",DS.vars.map((v,j)=>({v,j})),"Dependent (ثنائي)")+`<label class="fl">Covariates</label>${vpick("lgi",numVars(),true)}`,()=>{const d=+$("#lgd").value,iv=picked("lgi").filter(x=>x!==d);if(!iv.length){toast("اختر متغيرًا مستقلًا");return false}aLogit(d,iv)})},
 kmeans(){if(!needVars(1))return;dlg("K-Means Cluster Analysis",`<label class="fl">Variables</label>${vpick("kmv",numVars(),true)}<label class="fl" for="kmk">Number of Clusters</label><input type="number" id="kmk" min="2" max="10" value="3"><label class="row" style="gap:6px;margin-top:8px"><input type="checkbox" id="kms" checked> Save cluster membership</label>`,()=>{const js=picked("kmv");if(!js.length){toast("اختر متغيرًا");return false}aKMeans(js,Math.max(2,+$("#kmk").value||3),$("#kms").checked)})},
 factor(){if(!needVars(3))return;dlg("Factor Analysis",`<label class="fl">Variables</label>${vpick("fav",numVars(),true)}<label class="fl" for="fam">Extraction Method</label><select id="fam"><option value="pc">Principal components</option><option value="paf">Principal axis factoring</option></select><label class="fl" for="fan">Extract</label><select id="fan"><option value="0">Based on Eigenvalue greater than 1</option>${[1,2,3,4,5,6].map(i=>`<option value="${i}">Fixed number of factors: ${i}</option>`).join("")}</select><label class="row" style="gap:6px;margin-top:8px"><input type="checkbox" id="far" checked> Rotation: Varimax</label><label class="row" style="gap:6px"><input type="checkbox" id="fas" checked> Suppress small coefficients (< .30)</label>`,()=>{const js=picked("fav");if(js.length<3){toast("اختر 3 متغيرات على الأقل");return false}aFactor(js,{nf:+$("#fan").value,paf:$("#fam").value==="paf",rot:$("#far").checked,sup:$("#fas").checked?.3:0})})},
 ks1(){if(!needVars(1))return;dlg("One-Sample Kolmogorov-Smirnov Test (Normal)",`<label class="fl">Test Variable List</label>${vpick("ksv",numVars(),true)}`,()=>{const js=picked("ksv");if(!js.length){toast("اختر متغيرًا");return false}aKS(js)})},
 kw(){if(!needVars(1)||DS.vars.length<2)return toast("تحتاج متغيرًا ومتغير مجموعات");dlg("Kruskal-Wallis H (K Independent Samples)",vsel("kwd",numVars(),"Test Variable")+vsel("kwf",DS.vars.map((v,j)=>({v,j})),"Grouping Variable"),()=>{aKW(+$("#kwd").value,+$("#kwf").value)})},
 fried(){if(!needVars(2))return;dlg("Friedman Test (K Related Samples)",`<label class="fl">Test Variables</label>${vpick("frv",numVars(),true)}`,()=>{const js=picked("frv");if(js.length<2){toast("اختر متغيرين على الأقل");return false}aFried(js)})},
 chigof(){dlg("Chi-square Test (Goodness of Fit)",vsel("cgv",DS.vars.map((v,j)=>({v,j})),"Test Variable")+`<p class="muted" style="font-size:13.5px">Expected Values: All categories equal.</p>`,()=>{aChiGOF(+$("#cgv").value)})},
 binom(){dlg("Binomial Test",vsel("bnv2",DS.vars.map((v,j)=>({v,j})),"Test Variable (ثنائي)")+`<label class="fl" for="btp">Test Proportion</label><input type="number" step="any" id="btp" value="0.50">`,()=>{aBinom(+$("#bnv2").value,+$("#btp").value||.5)})},
 mva(){if(!DS.vars.length)return toast("لا توجد بيانات");aMissing();SA.tab="out"},
