 rel(){if(!needVars(2))return;dlg("Reliability Analysis",`<label class="fl">Items</label>${vpick("iv",numVars(),true)}<label class="fl" for="rlm">Model</label><select id="rlm"><option value="alpha">Alpha</option><option value="split">Split-half (Spearman-Brown + Guttman)</option></select><p class="muted" style="font-size:14px">اعكس البنود السالبة أولًا من Transform › Reverse Recode.</p>`,()=>{const js=picked("iv");if(js.length<2){toast("اختر بندين على الأقل");return false}$("#rlm").value==="split"?aRelSplit(js):aRel(js)})}
