function appAction(a){const NV=numVars(),ALL=DS.vars.map((v,j)=>({v,j}));
 if(a.startsWith("i:")){infoDlg(a.slice(2));return}
 if(MUT.has(a))snap();
 if(a.startsWith("ch:")){chartDlg(a.slice(3));return}
 if(APX[a]){APX[a]();if(ov.hidden)renderSpssApp();return}
 switch(a){
 case"new":if(DS.rows.length&&!confirm("سيتم مسح البيانات الحالية. متأكد؟"))return;DS=dsBlank();dsSave();SA.out=[];SA.tab="data";break;
 case"sample":if(DS.rows.length&&!confirm("سيتم استبدال البيانات الحالية ببيانات التدريب. متأكد؟"))return;DS=sampleDS();dsSave();SA.tab="data";SA.page=0;toast("تم تحميل بيانات تدريب: 48 طالبًا");break;
 case"import":{const inp=document.createElement("input");inp.type="file";inp.accept=".sav,.zsav,.xlsx,.xls,.csv,.txt,.tsv";inp.onchange=async()=>{const f=inp.files[0];if(!f)return;const nm=f.name.replace(/\.[^.]+$/,"");try{if(/\.z?sav$/i.test(f.name)){const r=await loadSav(await f.arrayBuffer());snap();DS={name:nm,vars:r.vars.map(v=>({...newVar(v.name,v.type),...v})),rows:r.rows};dsSave();SA.tab="data";SA.page=0;SA.filter=null;SA.split=null;toast(`تم فتح ${f.name}: ${r.rows.length} حالة و${r.vars.length} متغير`)}else if(/\.(xlsx|xls)$/i.test(f.name)){toast("جارٍ قراءة ملف Excel…");const X=await loadXLSX();const wb=X.read(await f.arrayBuffer(),{type:"array"});const ws=wb.Sheets[wb.SheetNames[0]];const aoa=X.utils.sheet_to_json(ws,{header:1,raw:true,defval:null});if(dsFromAOA(aoa,true,nm))toast(`تم استيراد ${DS.rows.length} حالة و${DS.vars.length} متغيرات من «${wb.SheetNames[0]}»`)}else{const aoa=parseDelim(await f.text());if(dsFromAOA(aoa,true,nm))toast(`تم استيراد ${DS.rows.length} حالة و${DS.vars.length} متغيرات`)}}catch(e){toast("تعذر قراءة الملف. جرّب حفظه CSV أو استخدم «لصق من إكسيل»")}renderSpssApp()};inp.click();return}
 case"paste":dlg("Paste from Excel — لصق من إكسيل",`<p class="muted" style="margin-top:0">في Excel حدد الجدول (مع صف العناوين) واضغط Ctrl+C، ثم الصقه هنا Ctrl+V.</p><textarea id="pt" style="min-height:220px" placeholder="gender	age	score"></textarea><label class="row" style="gap:6px;margin-top:8px"><input type="checkbox" id="ph" checked> الصف الأول يحتوي أسماء المتغيرات</label>`,()=>{const t=$("#pt").value;if(!t.trim()){toast("الصق البيانات أولًا");return false}if(DS.rows.length&&!confirm("سيتم استبدال البيانات الحالية. متأكد؟"))return false;const ok=dsFromAOA(parseDelim(t),$("#ph").checked,"Pasted");if(ok)toast(`تم لصق ${DS.rows.length} حالة و${DS.vars.length} متغيرات`);return ok},"استيراد");return;
 case"xlsx":exportXLSX();return;
 case"csv":exportCSV();return;
 case"addrow":DS.rows.push(DS.vars.map(()=>null));dsSave();SA.tab="data";SA.page=Math.floor((DS.rows.length)/100);break;
 case"addvar":addVar(newVar(nextVarName()));dsSave();SA.tab="var";break;
 case"delvar":if(!DS.vars.length)return;dlg("Delete Variable",vsel("dv",ALL,"اختر المتغير"),()=>{const j=+$("#dv").value;DS.vars.splice(j,1);DS.rows.forEach(r=>r.splice(j,1));dsSave()});return;
 case"sort":if(!DS.vars.length)return;dlg("Sort Cases",vsel("sv",ALL,"رتّب حسب")+`<label class="fl" for="so">الترتيب</label><select id="so"><option value="1">تصاعدي Ascending</option><option value="-1">تنازلي Descending</option></select>`,()=>{const j=+$("#sv").value,o=+$("#so").value;DS.rows.sort((a,b)=>{const x=a[j],y=b[j];if(x==null)return 1;if(y==null)return-1;return(typeof x==="number"&&typeof y==="number"?x-y:String(x).localeCompare(String(y)))*o});dsSave();SA.tab="data"});return;
 case"compute":if(!needVars(1))return;dlg("Compute Variable",`<label class="fl" for="cn">اسم المتغير الجديد (Target Variable)</label><input type="text" id="cn" value="total"><label class="fl" for="cf">الدالة</label><select id="cf"><option value="sum">SUM — مجموع (الدرجة الكلية)</option><option value="mean">MEAN — متوسط</option><option value="diff">الفرق: المتغير الأول − الثاني</option></select><label class="fl">المتغيرات</label>${vpick("cv",NV,true)}`,()=>{const js=picked("cv"),fn=$("#cf").value;if(!js.length||(fn==="diff"&&js.length!==2)){toast(fn==="diff"?"اختر متغيرين بالضبط":"اختر متغيرًا واحدًا على الأقل");return false}const name=uniqName($("#cn").value||"COMPUTE");const v=newVar(name);v.label=fn==="sum"?"مجموع "+js.map(j=>DS.vars[j].name).join("+"):fn==="mean"?"متوسط البنود":"الفرق";addVar(v);const t=DS.vars.length-1;DS.rows.forEach(r=>{const xs=js.map(j=>numOrNull(r[j]));if(xs.some(x=>x==null)){r[t]=null;return}r[t]=fn==="sum"?ST.sum(xs):fn==="mean"?ST.mean(xs):xs[0]-xs[1]});dsSave();SA.tab="data";toast("تم إنشاء المتغير "+name)});return;
 case"recode":if(!needVars(1))return;dlg("Reverse Recode — عكس البنود السالبة",`<p class="muted" style="margin-top:0">القيمة الجديدة = (أعلى + أدنى) − القيمة. مثال ليكرت خماسي: 5←1، 4←2، 3←3.</p><div class="g2"><div><label class="fl" for="rmn">أدنى قيمة</label><input type="number" id="rmn" value="1"></div><div><label class="fl" for="rmx">أعلى قيمة</label><input type="number" id="rmx" value="5"></div></div><label class="fl">البنود المراد عكسها</label>${vpick("rv",NV,true)}<label class="row" style="gap:6px;margin-top:8px"><input type="checkbox" id="rnew" checked> في متغيرات جديدة (اسم_r) بدل الكتابة فوق الأصل</label>`,()=>{const js=picked("rv"),mn=+$("#rmn").value,mx=+$("#rmx").value;if(!js.length){toast("اختر بندًا");return false}const nw=$("#rnew").checked;js.forEach(j=>{let t=j;if(nw){const ov2=DS.vars[j],v=newVar(uniqName(ov2.name+"_r"));v.label=(ov2.label||ov2.name)+" (معكوس)";v.measure=ov2.measure;v.dec=ov2.dec;v.values={...ov2.values};addVar(v);t=DS.vars.length-1}DS.rows.forEach(r=>{const x=numOrNull(r[j]);r[t]=x==null?null:mn+mx-x})});dsSave();SA.tab="data";toast("تم عكس "+js.length+" بنود")});return;
 case"freq":if(!needVars(1,ALL))return;dlg("Frequencies",`<label class="fl">Variable(s)</label>${vpick("fv",ALL,true)}`,()=>{const js=picked("fv");if(!js.length){toast("اختر متغيرًا");return false}aFreq(js)});return;
 case"desc":if(!needVars(1))return;dlg("Descriptives",`<label class="fl">Variable(s)</label>${vpick("dv2",NV,true)}`,()=>{const js=picked("dv2");if(!js.length){toast("اختر متغيرًا");return false}aDesc(js)});return;
 case"explore":if(!needVars(1))return;dlg("Explore — اختبار الاعتدالية",`<label class="fl">Dependent List</label>${vpick("ev",NV,true)}`,()=>{const js=picked("ev");if(!js.length){toast("اختر متغيرًا");return false}aExplore(js)});return;
 case"cross":if(!needVars(2,ALL))return;dlg("Crosstabs",vsel("cr",ALL,"Row(s) — الصفوف")+vsel("cc",ALL,"Column(s) — الأعمدة")+`<label class="row" style="gap:6px;margin-top:10px"><input type="checkbox" id="cchi" checked> Chi-square كا²</label><label class="row" style="gap:6px"><input type="checkbox" id="ck"> Kappa (اتفاق مصححين)</label>`,()=>{aCross(+$("#cr").value,+$("#cc").value,$("#cchi").checked,$("#ck").checked)});setTimeout(()=>{const s=$("#cc");if(s&&s.options.length>1)s.selectedIndex=1},0);return;
 case"t1":if(!needVars(1))return;dlg("One-Sample T Test",`<label class="fl">Test Variable(s)</label>${vpick("tv",NV,true)}<label class="fl" for="tval">Test Value — قيمة المجتمع</label><input type="number" id="tval" step="any" value="0">`,()=>{const js=picked("tv");if(!js.length){toast("اختر متغيرًا");return false}aT1(js,+$("#tval").value||0)});return;
 case"tind":if(!needVars(1)||DS.vars.length<2)return toast("تحتاج متغيرًا تابعًا ومتغيرًا للمجموعات");dlg("Independent-Samples T Test",`<label class="fl">Test Variable(s) — المتغير التابع</label>${vpick("tv",NV,true)}${vsel("gv",ALL,"Grouping Variable — متغير المجموعات")}${groupInputs()}`,()=>{const js=picked("tv");if(!js.length){toast("اختر متغيرًا تابعًا");return false}aTind(js,+$("#gv").value,gv($("#g1").value),gv($("#g2").value))});wireGroups();return;
 case"tpair":if(!needVars(2))return;dlg("Paired-Samples T Test",vsel("p1",NV,"Variable 1 — القياس الأول (قبلي)")+vsel("p2",NV,"Variable 2 — القياس الثاني (بعدي)"),()=>{if($("#p1").value===$("#p2").value){toast("اختر متغيرين مختلفين");return false}aTpair(+$("#p1").value,+$("#p2").value)});setTimeout(()=>{const s=$("#p2");if(s&&s.options.length>1)s.selectedIndex=1},0);return;
 case"anova":if(!needVars(1)||DS.vars.length<2)return toast("تحتاج متغيرًا تابعًا ومتغير مجموعات");dlg("One-Way ANOVA",`<label class="fl">Dependent List — المتغير التابع</label>${vpick("av",NV,true)}${vsel("af",ALL,"Factor — المتغير المستقل (3 مجموعات فأكثر)")}<label class="row" style="gap:6px;margin-top:10px"><input type="checkbox" id="aph" checked> Post Hoc: Bonferroni</label>`,()=>{const js=picked("av");if(!js.length){toast("اختر متغيرًا تابعًا");return false}aAnova(js,+$("#af").value,$("#aph").checked)});return;
 case"corr":if(!needVars(2))return;dlg("Bivariate Correlations",`<label class="fl">Variables</label>${vpick("rv2",NV,true)}<label class="fl" for="cm">Correlation Coefficients</label><select id="cm"><option value="pearson">Pearson</option><option value="spearman">Spearman</option></select>`,()=>{const js=picked("rv2");if(js.length<2){toast("اختر متغيرين على الأقل");return false}aCorr(js,$("#cm").value)});return;
 case"rel":if(!needVars(2))return;dlg("Reliability Analysis — ألفا كرونباخ",`<label class="fl">Items — البنود</label>${vpick("iv",NV,true)}<p class="muted" style="font-size:14px">اعكس البنود السالبة أولًا من Transform › Reverse Recode.</p>`,()=>{const js=picked("iv");if(js.length<2){toast("اختر بندين على الأقل");return false}aRel(js)});return;
 case"mw":if(!needVars(1)||DS.vars.length<2)return toast("تحتاج متغيرًا تابعًا ومتغير مجموعات");dlg("Mann-Whitney U",vsel("mv",NV,"Test Variable")+vsel("gv",ALL,"Grouping Variable")+groupInputs(),()=>{aMW(+$("#mv").value,+$("#gv").value,gv($("#g1").value),gv($("#g2").value))});wireGroups();return;
 case"wil":if(!needVars(2))return;dlg("Wilcoxon Signed Ranks",vsel("w1",NV,"Variable 1")+vsel("w2",NV,"Variable 2"),()=>{if($("#w1").value===$("#w2").value){toast("اختر متغيرين مختلفين");return false}aWil(+$("#w1").value,+$("#w2").value)});setTimeout(()=>{const s=$("#w2");if(s&&s.options.length>1)s.selectedIndex=1},0);return;
 }
 renderSpssApp();
}
const MACT=[];function menuHTML(list){return list.map(it=>Array.isArray(it[1])?`<button class="sub">${esc(it[0])}<span>▸</span></button><div class="subm" hidden>${menuHTML(it[1])}</div>`:`<button data-a="${MACT.push(it[1])-1}" class="${String(it[1]).startsWith("i:")?"na":""}"><span class="mico">${typeof MENUI!=="undefined"&&MENUI[it[1]]&&TBI[MENUI[it[1]]]?TBI[MENUI[it[1]]].replace(/width="22" height="22"/,'width="15" height="15"'):""}</span>${esc(it[0])}</button>`).join("")}
let _seg="";
